#include "..\H\typedef.h"
#include "RTT\RTT_ex.h"

#include "osal.h"
#include "osal_api.h"

#include "os_perf_timer.h"

//perfomance test for OS

//config: ============================================================
//число проходов для усреднения результатов
#define TEST_PASS_NUM 64

//включение тестов конкретных сервисов OS
#define PERFTEST_QUEUE
#define PERFTEST_EVF
#define PERFTEST_SEM
#define PERFTEST_MTX

//режимы сбора статистики производительности
// разрешить счетчики PMU
#define PMU_MODE_ENABLE
// разрешить таймер Cortex-A7
#define TRM_MODE_ENABLE
// разрешить дополнительные метрики PMU
#define PMU_METRIC_ENABLE

//частота таймера A7
#define TRM_FREQ_MHZ 24

//запускать на разных ядрах
//#define DIFFERENT_CORES

//config: ============================================================

//взаимоблокировки конфигурации
#ifdef MPCORE_MODE
 #ifdef DIFFERENT_CORES
 //замер только таймером
 #undef PMU_MODE_ENABLE
 #define TRM_MODE_ENABLE
 #endif
#endif

#ifndef PMU_MODE_ENABLE
 #undef PMU_METRIC_ENABLE
#endif

extern DWORD getCPU_clk(void);
extern DWORD OS_BSP_getCPUClock(void);
extern WORD dig_itoa(BYTE *dst,int v,DWORD off,BYTE i,BYTE f,BYTE signMode);

enum {PERF_QU_SID,PERF_EVF_SID,PERF_SEM_SID,PERF_MTX_SID,PERF_SID_TOTAL};
enum _TEST_EVFS {QU_MEASURE=1,EVF_MEASURE=2,SEM_MEASURE=4,MTX_MEASURE=8};
#define EVF_PERFTEST 1

typedef struct _OS_PERF_DATA_ENTRY
{
DWORD c_min; //pmu cycles
DWORD c_max;
DWORD c_total;
DWORD i_min; //pmu instructions
DWORD i_max;
DWORD i_total;
DWORD t_min; //trm ticks
DWORD t_max;
DWORD t_total;
DWORD pmu_M1_total; //pmu metric1
DWORD pmu_M2_total; //pmu metric2
}OS_PERF_DATA_ENTRY;

typedef struct _OS_PERF_DATA
{
DWORD pass;
OS_PERF_DATA_ENTRY pdEntry[PERF_SID_TOTAL];
}OS_PERF_DATA;

typedef struct _OS_PERF_COUNTERS
{
DWORD pmuM1[PERF_SID_TOTAL];
DWORD pmuM2[PERF_SID_TOTAL];
DWORD cyc[PERF_SID_TOTAL];
DWORD instr[PERF_SID_TOTAL];
QWORD tt[PERF_SID_TOTAL];
}OS_PERF_COUNTERS;

//RTOS objects -------------------------------------------
//#pragma default_variable_attributes = @ "DATA_NO_CACHE"
//#pragma default_variable_attributes = @ "SRAM"
