 #define TEST1_PRIORITY (PRIO_LVL 15)
 #define TEST2_PRIORITY (PRIO_LVL 16)
 #define TEST3_PRIORITY (PRIO_LVL 17)

 #define TEST1_QUEUE_LEN 8
 #define TEST1_QUEUE_MSGSIZE 1

 #define TEST1_STACK_SIZE 128
 #define TEST2_STACK_SIZE 128
