 #pragma data_alignment=64
 OS_TASK_STACK TEST1ThreadStack[TEST1_STACK_SIZE];
 #pragma data_alignment=64
 OS_TASK_CB TEST2Thread;
 #pragma data_alignment=64
 OS_TASK_STACK TEST2ThreadStack[TEST2_STACK_SIZE];
 #pragma data_alignment=64
 OS_TASK_STACK TEST3ThreadStack[TEST3_STACK_SIZE];
