#pragma default_variable_attributes=

//counters -------------------------------------------------
#pragma default_variable_attributes = @ "DATA_NO_CACHE"
 /*
 //counters --------------
 #pragma data_alignment=64
 OS_PERF_COUNTERS cnt1;
 #pragma data_alignment=64
 OS_PERF_COUNTERS cnt2;
 DWORD sid2;
 #pragma data_alignment=64
