#include "..\h\typedef.h"

#include "DBGUTIL\pmu\sys_pmu.h"
#include "os_perf_timer.h"

extern DWORD OS_BSP_getPMU0Address(void);
extern DWORD getCPUID(void);

static DWORD pmuInited=0;
void OS_perfTimerInit(void)
{
_pmuInit_();
_pmuSetCountEvent_(0,PMU_INST_ARCH_EXECUTED);

_pmuSetCountEvent_(1,0x10); //
_pmuSetCountEvent_(2,0x12); //0x68

pmuInited=1;
}

void OS_perfTimerStop(void)
{
_pmuStopCounters_(pmuCYCLE_COUNTER|pmuCOUNTER0|pmuCOUNTER1|pmuCOUNTER2);
}

DWORD OS_perfTimerGetCycle(void)
{
return(_pmuGetCycleCount_());
}

DWORD OS_perfTimerGetCnt0(void)
{
return(_pmuGetEventCount_(0));
}

DWORD OS_perfTimerGetCnt1(void)
{
return(_pmuGetEventCount_(1));
}

DWORD OS_perfTimerGetCnt2(void)
{
return(_pmuGetEventCount_(2));
}

void OS_perfTimerStart(void)
{
if(!pmuInited){_pmuInit_();}
_pmuResetCounters_();
_pmuStartCounters_(pmuCYCLE_COUNTER|pmuCOUNTER0|pmuCOUNTER1|pmuCOUNTER2);
}

DWORD pmuerr=0;
DWORD OS_perfTime(DWORD t1,DWORD t2)
{
DWORD t;
if(t2>=t1)
 {t=t2-t1;}
else
 {t=t2+(0xFFFFFFFF-t1);}
return(t);
}

DWORD OS_perfTime4(QWORD t1,QWORD t2)
{
DWORD t;

if(t2>=t1)
 {t=t2-t1;}
else
 {t=t2+(0xFFFFFFFFFFFFFFFF-t1);}
return(t);
}

QWORD OS_perfA7TRM_ticks(void)
{
DWORD low,high;
asm("MRRC p15, 0, %0, %1, c14" : "=r"(low), "=r"(high));
return(((QWORD)high<<32)|low);
}
Здесь используются врапперы OSAL (OS Abstraction Layer), написанные много лет назад для безболезненной замены rtos в проекте. Тот проект проделал путь threadx→freertos→embos по определенным причинам, не относящимся к теме данной статьи.
